package com.bank.optimize;

// Describes an image's size contributors (all in MB).
public class ImageSpec {
    private int baseMb;         // base image
    private int toolchainMb;    // build tools (should become 0 with multi-stage)
    private int contextJunkMb;  // .git, caches, etc. (should become 0 with .dockerignore)
    private int pkgCacheMb;     // leftover package caches (0 if cleaned same-layer)
    private final int artifactMb;

    public ImageSpec(int baseMb, int toolchainMb, int contextJunkMb,
                     int pkgCacheMb, int artifactMb) {
        this.baseMb = baseMb;
        this.toolchainMb = toolchainMb;
        this.contextJunkMb = contextJunkMb;
        this.pkgCacheMb = pkgCacheMb;
        this.artifactMb = artifactMb;
    }
    public int total() { return baseMb + toolchainMb + contextJunkMb + pkgCacheMb + artifactMb; }

    public void setBaseMb(int mb)        { this.baseMb = mb; }
    public void setToolchainMb(int mb)   { this.toolchainMb = mb; }
    public void setContextJunkMb(int mb) { this.contextJunkMb = mb; }
    public void setPkgCacheMb(int mb)    { this.pkgCacheMb = mb; }
}
