package com.bank.optimize;

import java.util.logging.Logger;

// Applies each size-reduction technique and reports the running total.
public class Optimizer {
    private static final Logger log = Logger.getLogger(Optimizer.class.getName());

    public void useSlimBase(ImageSpec spec, int slimBaseMb) {
        spec.setBaseMb(slimBaseMb);
        log.info(() -> "Slim/distroless base -> base now " + slimBaseMb + "MB. Total=" + spec.total() + "MB");
    }

    public void multiStage(ImageSpec spec) {
        spec.setToolchainMb(0); // toolchain stays in the discarded build stage
        log.info(() -> "Multi-stage build -> toolchain dropped. Total=" + spec.total() + "MB");
    }

    public void dockerignore(ImageSpec spec) {
        spec.setContextJunkMb(0); // .git, caches never sent/copied
        log.info(() -> ".dockerignore -> context junk dropped. Total=" + spec.total() + "MB");
    }

    public void cleanLayersSameStep(ImageSpec spec) {
        spec.setPkgCacheMb(0); // install + clean in one RUN
        log.info(() -> "Clean caches in same layer -> pkg cache dropped. Total=" + spec.total() + "MB");
    }
}
