package com.bank.optimize;

import java.util.logging.*;

public class ImageOptimizeDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new OptimizeLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(ImageOptimizeDemo.class.getName());

        // Start: full OS+JDK base, toolchain, context junk, uncleaned caches, 45MB JAR.
        ImageSpec spec = new ImageSpec(700, 300, 120, 60, 45);
        log.info("Unoptimized image total = " + spec.total() + "MB");

        Optimizer opt = new Optimizer();
        opt.useSlimBase(spec, 230);       // full OS+JDK -> slim JRE
        opt.multiStage(spec);             // drop build toolchain
        opt.dockerignore(spec);           // drop .git/caches from context
        opt.cleanLayersSameStep(spec);    // drop leftover package caches

        log.info("Optimized image total = " + spec.total() + "MB");
    }
}

// ─── Would be in OptimizeLogFormatter.java in a real project ───
class OptimizeLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
