FROM maven:3.9-eclipse-temurin-21 AS build
WORKDIR /app
COPY pom.xml .
RUN mvn dependency:go-offline          # cache deps before source (caching)
COPY src ./src
RUN mvn clean package -DskipTests

# Stage 2: slim/distroless runtime, only the artifact
FROM gcr.io/distroless/java21-debian12   # no shell, no pkg-manager
WORKDIR /app
COPY --from=build /app/target/transfer-service.jar /app/app.jar
ENTRYPOINT ["app.jar"]
# Minimal base + multi-stage + narrow copy + .dockerignore = small, secure image
